import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import type { DialogueNode } from '@/lib/types'

const mockPlaySFX = vi.fn()

vi.mock('@/components/audio/AudioManager', () => ({
  useAudio: () => ({ muted: false, toggleMute: vi.fn(), playSFX: mockPlaySFX }),
  AudioToggle: () => <button>Audio</button>,
  AudioProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}))

vi.mock('@/lib/data/crew', () => ({
  crewMembers: [
    {
      id: '[REDACTED_PROJECT]',
      name: 'ARIA',
      role: 'Ship AI / Narrator',
      agentPhase: 'Orchestrator',
      description: 'Your ship AI.',
      recruitedAt: 'start',
      portrait: '/images/characters/[REDACTED_PROJECT].svg',
      color: '#4a6fa5',
      quote: 'Every great journey begins with a single prompt.',
    },
    {
      id: 'scout',
      name: 'Scout',
      role: 'Perception Specialist',
      agentPhase: 'Perceive',
      description: 'Sees everything.',
      recruitedAt: 'agent-academy-m1',
      portrait: '/images/characters/scout.svg',
      color: '#6b9e78',
      quote: 'The world is data.',
    },
  ],
}))

import { DialogueSystem } from '@/components/game/DialogueSystem'

// Helper: simple dialogue with no choices
function makeSimpleNodes(count: number): DialogueNode[] {
  return Array.from({ length: count }, (_, i) => ({
    speaker: '[REDACTED_PROJECT]',
    text: `Dialogue line ${i + 1}`,
  }))
}

// Helper: dialogue with a choice node
function makeChoiceNodes(): DialogueNode[] {
  return [
    { speaker: '[REDACTED_PROJECT]', text: 'What is vibe coding?' },
    {
      speaker: '[REDACTED_PROJECT]',
      text: 'Pick the correct answer:',
      choices: [
        { text: 'Writing code with AI assistance', correct: true, response: 'Correct!' },
        { text: 'Playing music while coding', correct: false, response: 'Not quite.' },
      ],
    },
    { speaker: '[REDACTED_PROJECT]', text: 'Good job, commander.' },
  ]
}

describe('DialogueSystem', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    mockPlaySFX.mockClear()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('renders the first dialogue node speaker name and text', async () => {
    const nodes = makeSimpleNodes(2)
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Speaker name should be rendered (ARIA from our mock crew)
    expect(screen.getByText('ARIA')).toBeInTheDocument()
    expect(screen.getByText('Ship AI / Narrator')).toBeInTheDocument()

    // Text should eventually appear via TypewriterText
    // Fast-forward timers to let typewriter complete
    act(() => {
      vi.advanceTimersByTime(5000)
    })
    await waitFor(() => {
      expect(screen.getByText('Dialogue line 1')).toBeInTheDocument()
    })
  })

  it('shows progress indicator with correct count', () => {
    const nodes = makeSimpleNodes(5)
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    expect(screen.getByText('1 / 5')).toBeInTheDocument()
  })

  it('advances through dialogue when clicking the text area', async () => {
    const nodes = makeSimpleNodes(3)
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Let typewriter complete for first node
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Dialogue line 1')).toBeInTheDocument()
    })

    // Click the text area to advance to next node
    const textArea = screen.getByRole('button')
    fireEvent.click(textArea)

    // Now on node 2
    expect(screen.getByText('2 / 3')).toBeInTheDocument()

    // Let typewriter complete for second node
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Dialogue line 2')).toBeInTheDocument()
    })
  })

  it('renders choice buttons when a node has choices', async () => {
    const nodes = makeChoiceNodes()
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Advance past first node
    act(() => {
      vi.advanceTimersByTime(5000)
    })
    await waitFor(() => {
      expect(screen.getByText('What is vibe coding?')).toBeInTheDocument()
    })

    // Click to advance to the choice node
    const textArea = screen.getByRole('button')
    fireEvent.click(textArea)

    // Let typewriter complete on choice node
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    // Choices should now be visible
    await waitFor(() => {
      expect(screen.getByText('Writing code with AI assistance')).toBeInTheDocument()
      expect(screen.getByText('Playing music while coding')).toBeInTheDocument()
    })
  })

  it('shows correct feedback when picking the right choice', async () => {
    const nodes = makeChoiceNodes()
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Advance to choice node
    act(() => {
      vi.advanceTimersByTime(5000)
    })
    await waitFor(() => {
      expect(screen.getByText('What is vibe coding?')).toBeInTheDocument()
    })
    fireEvent.click(screen.getByRole('button'))

    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Writing code with AI assistance')).toBeInTheDocument()
    })

    // Click the correct choice
    fireEvent.click(screen.getByText('Writing code with AI assistance'))

    // Feedback should appear
    await waitFor(() => {
      expect(screen.getByText('Correct')).toBeInTheDocument()
      expect(screen.getByText('Correct!')).toBeInTheDocument()
    })

    expect(mockPlaySFX).toHaveBeenCalledWith('success')
  })

  it('shows wrong feedback when picking the incorrect choice', async () => {
    const nodes = makeChoiceNodes()
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Advance to choice node
    act(() => {
      vi.advanceTimersByTime(5000)
    })
    fireEvent.click(screen.getByRole('button'))
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Playing music while coding')).toBeInTheDocument()
    })

    // Click the wrong choice
    fireEvent.click(screen.getByText('Playing music while coding'))

    // Feedback should appear
    await waitFor(() => {
      expect(screen.getByText('Not quite')).toBeInTheDocument()
      expect(screen.getByText('Not quite.')).toBeInTheDocument()
    })

    expect(mockPlaySFX).toHaveBeenCalledWith('error')
  })

  it('calls onComplete when dialogue finishes and Continue is clicked', async () => {
    const onComplete = vi.fn()
    const nodes = makeSimpleNodes(1)
    render(<DialogueSystem nodes={nodes} onComplete={onComplete} />)

    // Let typewriter complete
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Dialogue line 1')).toBeInTheDocument()
    })

    // Click to advance past the last node, which triggers the summary screen
    fireEvent.click(screen.getByRole('button'))

    // Summary screen should show
    await waitFor(() => {
      expect(screen.getByText('Dialogue Complete')).toBeInTheDocument()
    })

    // Click "Continue" to trigger onComplete
    fireEvent.click(screen.getByText('Continue'))
    expect(onComplete).toHaveBeenCalledWith(100) // No questions = 100% score
  })

  it('calculates score based on correct answers and shows it on summary', async () => {
    // Two choice nodes: answer one correct, one wrong
    const nodes: DialogueNode[] = [
      {
        speaker: '[REDACTED_PROJECT]',
        text: 'Question 1',
        choices: [
          { text: 'Right answer', correct: true, response: 'Yes!' },
          { text: 'Wrong answer', correct: false, response: 'No.' },
        ],
      },
      {
        speaker: '[REDACTED_PROJECT]',
        text: 'Question 2',
        choices: [
          { text: 'Bad answer', correct: false, response: 'Nope.' },
          { text: 'Good answer', correct: true, response: 'Great!' },
        ],
      },
    ]

    const onComplete = vi.fn()
    render(<DialogueSystem nodes={nodes} onComplete={onComplete} />)

    // Let typewriter complete for Q1
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Right answer')).toBeInTheDocument()
    })

    // Answer Q1 correctly
    fireEvent.click(screen.getByText('Right answer'))
    expect(mockPlaySFX).toHaveBeenCalledWith('success')

    // Wait for auto-advance after correct feedback (1200ms)
    act(() => {
      vi.advanceTimersByTime(1500)
    })

    // Let typewriter complete for Q2
    act(() => {
      vi.advanceTimersByTime(5000)
    })

    await waitFor(() => {
      expect(screen.getByText('Bad answer')).toBeInTheDocument()
    })

    // Answer Q2 incorrectly
    fireEvent.click(screen.getByText('Bad answer'))

    // Wait for auto-advance after wrong feedback (2000ms)
    act(() => {
      vi.advanceTimersByTime(2500)
    })

    // Summary screen shows 1/2
    await waitFor(() => {
      expect(screen.getByText('Dialogue Complete')).toBeInTheDocument()
      expect(screen.getByText('1/2')).toBeInTheDocument()
      expect(screen.getByText('correct answers')).toBeInTheDocument()
    })

    // Click Continue, score should be 50%
    fireEvent.click(screen.getByText('Continue'))
    expect(onComplete).toHaveBeenCalledWith(50)
  })

  it('shows "Briefing acknowledged" on summary when there are no questions', async () => {
    const nodes = makeSimpleNodes(1)
    const onComplete = vi.fn()
    render(<DialogueSystem nodes={nodes} onComplete={onComplete} />)

    act(() => {
      vi.advanceTimersByTime(5000)
    })

    fireEvent.click(screen.getByRole('button'))

    await waitFor(() => {
      expect(screen.getByText('Briefing acknowledged.')).toBeInTheDocument()
    })
  })

  it('uses fallback speaker info for unknown speaker IDs', () => {
    const nodes: DialogueNode[] = [
      { speaker: 'unknown-person', text: 'Hello there.' },
    ]
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Fallback: uses speakerId as name
    expect(screen.getByText('unknown-person')).toBeInTheDocument()
    expect(screen.getByText('Unknown')).toBeInTheDocument()
  })

  it('shows score tracker when there are question nodes', async () => {
    const nodes: DialogueNode[] = [
      {
        speaker: '[REDACTED_PROJECT]',
        text: 'A question',
        choices: [
          { text: 'Option A', correct: true },
          { text: 'Option B', correct: false },
        ],
      },
    ]
    render(<DialogueSystem nodes={nodes} onComplete={vi.fn()} />)

    // Score tracker should be visible: "Score: 0/1"
    expect(screen.getByText('Score: 0/1')).toBeInTheDocument()
  })
})

import { render, screen } from '@testing-library/react'
import * as navigation from 'next/navigation'

vi.mock('@/components/audio/AudioManager', () => ({
  useAudio: () => ({ muted: false, toggleMute: vi.fn(), playSFX: vi.fn() }),
  AudioToggle: () => <button>Audio</button>,
  AudioProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}))

import { NavBar } from '@/components/game/NavBar'

describe('NavBar', () => {
  function renderWithPathname(pathname: string) {
    vi.spyOn(navigation, 'usePathname').mockReturnValue(pathname)
    return render(<NavBar />)
  }

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('renders all five nav items on a game route', () => {
    renderWithPathname('/cockpit')

    expect(screen.getByText('Map')).toBeInTheDocument()
    expect(screen.getByText('Cockpit')).toBeInTheDocument()
    expect(screen.getByText('Crew')).toBeInTheDocument()
    expect(screen.getByText('Items')).toBeInTheDocument()
    expect(screen.getByText('Academy')).toBeInTheDocument()
  })

  it('renders the audio toggle', () => {
    renderWithPathname('/cockpit')
    // AudioToggle renders a button with text "Audio" (from our mock)
    // Plus the label "Audio" below it
    const audioElements = screen.getAllByText('Audio')
    expect(audioElements.length).toBeGreaterThanOrEqual(1)
  })

  it('does NOT render on the title screen (pathname "/")', () => {
    const { container } = renderWithPathname('/')
    expect(container.innerHTML).toBe('')
  })

  it('does NOT render on the character creation screen (pathname "/create")', () => {
    const { container } = renderWithPathname('/create')
    expect(container.innerHTML).toBe('')
  })

  it('renders on the cockpit route', () => {
    renderWithPathname('/cockpit')
    expect(screen.getByRole('navigation')).toBeInTheDocument()
  })

  it('renders on the starmap route', () => {
    renderWithPathname('/starmap')
    expect(screen.getByRole('navigation')).toBeInTheDocument()
  })

  it('renders on planet sub-routes', () => {
    renderWithPathname('/planets/vibe-world')
    expect(screen.getByRole('navigation')).toBeInTheDocument()
  })

  it('highlights the active nav item for /cockpit', () => {
    renderWithPathname('/cockpit')

    const cockpitLink = screen.getByText('Cockpit').closest('a')
    expect(cockpitLink).toHaveClass('text-starlight')

    // Other items should not have the active class
    const mapLink = screen.getByText('Map').closest('a')
    expect(mapLink).toHaveClass('text-starlight-dim')
  })

  it('highlights the active nav item for /starmap', () => {
    renderWithPathname('/starmap')

    const mapLink = screen.getByText('Map').closest('a')
    expect(mapLink).toHaveClass('text-starlight')

    const cockpitLink = screen.getByText('Cockpit').closest('a')
    expect(cockpitLink).toHaveClass('text-starlight-dim')
  })

  it('highlights Academy when on /academy sub-route', () => {
    renderWithPathname('/academy/section-1')

    const academyLink = screen.getByText('Academy').closest('a')
    expect(academyLink).toHaveClass('text-starlight')
  })

  it('nav items link to correct routes', () => {
    renderWithPathname('/cockpit')

    expect(screen.getByText('Map').closest('a')).toHaveAttribute('href', '/starmap')
    expect(screen.getByText('Cockpit').closest('a')).toHaveAttribute('href', '/cockpit')
    expect(screen.getByText('Crew').closest('a')).toHaveAttribute('href', '/crew')
    expect(screen.getByText('Items').closest('a')).toHaveAttribute('href', '/inventory')
    expect(screen.getByText('Academy').closest('a')).toHaveAttribute('href', '/academy')
  })
})

